/**
 * Expo config plugin: give the Android app a network security configuration
 * that trusts certificate authorities the device's owner installed, next to
 * the system ones. See ./networkSecurityConfig.js for what the file contains
 * and why.
 *
 * `android/` is generated by `expo prebuild` and never committed, so both the
 * resource file and the manifest attribute are written here.
 *
 * Plain CommonJS on purpose: Expo transpiles app.config.ts itself, but a file
 * it requires is loaded by Node as is, and the EAS build image runs a Node
 * that cannot load TypeScript.
 */
const fs = require('fs');
const path = require('path');
const { AndroidConfig, withAndroidManifest, withDangerousMod } = require('expo/config-plugins');

const {
  NETWORK_SECURITY_CONFIG_RESOURCE,
  NETWORK_SECURITY_CONFIG_XML,
  applyNetworkSecurityConfig,
} = require('./networkSecurityConfig');

function withNetworkSecurityConfig(config) {
  config = withDangerousMod(config, [
    'android',
    async (cfg) => {
      const dir = path.join(cfg.modRequest.platformProjectRoot, 'app', 'src', 'main', 'res', 'xml');
      await fs.promises.mkdir(dir, { recursive: true });
      await fs.promises.writeFile(
        path.join(dir, `${NETWORK_SECURITY_CONFIG_RESOURCE}.xml`),
        NETWORK_SECURITY_CONFIG_XML,
      );
      return cfg;
    },
  ]);
  return withAndroidManifest(config, (cfg) => {
    applyNetworkSecurityConfig(AndroidConfig.Manifest.getMainApplicationOrThrow(cfg.modResults));
    return cfg;
  });
}

module.exports = withNetworkSecurityConfig;
